/* ================= Módulos clínicos (lab, documentos, vacinas, reprodução, anestesia, emergência, produção, quiz) ================= */
const LABREF=DATA.labref||[],VACS=DATA.vac||{},GESTS=DATA.gest||{};
function tabsBar(base,tabs,cur){return '<div class="chips">'+tabs.map(([k,l])=>'<a class="chip '+(cur===k?"on":"")+'" href="#/'+base+'/'+k+'" style="text-decoration:none">'+l+'</a>').join("")+'</div>'}
function selF(id,label,opts,val,on){return '<div class="field"><label for="'+id+'">'+label+'</label><select class="inp" id="'+id+'" onchange="'+(on||"")+'">'+opts.map(o=>{const v=Array.isArray(o)?o[0]:o,t=Array.isArray(o)?o[1]:o;return '<option value="'+esc(v)+'" '+(String(val)===String(v)?"selected":"")+'>'+esc(t)+'</option>'}).join("")+'</select></div>'}
function txtF(obj,k,label,ph,area){const v=esc((S[obj]||{})[k]||"");const on='oninput="S.'+obj+'[\''+k+'\']=this.value;saveMod(\''+obj+'\')"';return '<div class="field"><label>'+label+'</label>'+(area?'<textarea class="inp" '+on+' placeholder="'+esc(ph||"")+'">'+v+'</textarea>':'<input class="inp" '+on+' value="'+v+'" placeholder="'+esc(ph||"")+'" />')+'</div>'}
function saveMod(k){store.set("m_"+k,S[k])}
function loadMod(k,d){if(!S[k])S[k]=store.get("m_"+k,d);return S[k]}
function addDays(d,n){const x=new Date(d.getTime());x.setDate(x.getDate()+n);return x}
function dBR(d){return d.toLocaleDateString("pt-BR")}
function parseDate(s){if(!s)return null;const m=String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return null;return new Date(+m[1],+m[2]-1,+m[3],12)}
function printBlock(title,inner,nome){const D=S.doc;document.getElementById("printArea").innerHTML='<div class="rx-page"><div class="rx-h"><b>'+esc(D.clinica||title)+'</b>'+(D.nome?'<br/>Médico(a)-Veterinário(a): '+esc(D.nome)+(D.crmv?" — CRMV "+esc(D.crmv):""):"")+'<br/><small>'+esc(D.end||"")+(D.tel?" · "+esc(D.tel):"")+'</small></div>'+inner+'</div>';
  if(window.AndroidPrint&&AndroidPrint.print){setTimeout(()=>{try{AndroidPrint.print(nome||title)}catch(e){}},250);return}try{window.print()}catch(e){}}

/* ---------- 1. Interpretação laboratorial ---------- */
function vLab(arg){arg=arg||"exames";const L=loadMod("lab",{sp:"dog",v:{}});
 const tabs=[["exames","Hemograma & bioquímica"],["gaso","Gasometria"],["ref","Valores de referência"]];let body="";
 if(arg==="exames"){const groups=[...new Set(LABREF.map(x=>x[5]))];
  body='<div class="card">'+selF("lbSp","Espécie",[["dog","Cão"],["cat","Gato"]],L.sp,"S.lab.sp=this.value;saveMod('lab');rerender()")+'<p class="xs muted" style="margin:6px 0 0">Preencha só o que tiver. As faixas são as usuais da literatura e variam entre laboratórios/equipamentos — prefira sempre a referência do laudo.</p></div>'+
  groups.map(g=>'<div class="card"><h3>'+g+'</h3><div class="grid g2m" style="margin-top:8px">'+LABREF.filter(x=>x[5]===g).map(x=>{const r=L.sp==="cat"?x[4]:x[3];return '<div class="field"><label>'+esc(x[1])+(x[2]?' ('+esc(x[2])+')':'')+' <span class="muted">'+r[0]+'–'+r[1]+'</span></label><input class="inp" type="number" inputmode="decimal" step="any" value="'+esc(L.v[x[0]]==null?"":L.v[x[0]])+'" oninput="labSet(\''+x[0]+'\',this.value)" /></div>'}).join("")+'</div></div>').join("")+
  '<div class="out" id="labOut"></div><div class="actions"><button class="btn" onclick="copy(labText())">'+ic("copy",18)+' Copiar laudo interpretado</button><button class="btn" onclick="S.lab.v={};saveMod(\'lab\');rerender()">'+ic("trash",18)+' Limpar</button></div>'+(AFTER.push(labRun),"")}
 if(arg==="gaso"){const G=loadMod("gaso",{sp:"dog",cr:"a"});const fld=(k,l,v)=>'<div class="field"><label>'+l+'</label><input class="inp" type="number" inputmode="decimal" step="any" value="'+esc(G[k]==null?"":G[k])+'" oninput="S.gaso.'+k+'=this.value;saveMod(\'gaso\');gasRun()" placeholder="'+(v||"")+'" /></div>';
  body='<div class="card grid g2m">'+selF("gsSp","Espécie",[["dog","Cão"],["cat","Gato"]],G.sp,"S.gaso.sp=this.value;saveMod('gaso');gasRun()")+selF("gsCr","Distúrbio respiratório (se houver)",[["a","Agudo (< 2–3 dias)"],["c","Crônico"]],G.cr,"S.gaso.cr=this.value;saveMod('gaso');gasRun()")+
  fld("ph","pH","7,40")+fld("pco2","pCO₂ (mmHg)","37")+fld("hco3","HCO₃⁻ (mEq/L)","22")+fld("be","Excesso de base (BE)","0")+fld("na","Na⁺ (mEq/L)","146")+fld("k","K⁺ (mEq/L)","4,5")+fld("cl","Cl⁻ (mEq/L)","110")+fld("alb","Albumina (g/dL) — opcional","3,0")+fld("lac","Lactato (mmol/L) — opcional","1,5")+'</div><div class="out" id="gasOut"></div>'+
  '<p class="xs muted">Compensações esperadas: fórmulas de de Morais & DiBartola (cães). Em gatos a compensação respiratória da acidose metabólica é pouco eficiente — interprete com cautela. Amostra venosa: pH ~0,03–0,05 menor e pCO₂ ~4–6 mmHg maior que arterial; para avaliar oxigenação (pO₂) use amostra ARTERIAL.</p>'+(AFTER.push(gasRun),"")}
 if(arg==="ref")body='<div class="card scroll-x"><table class="tbl"><thead><tr><th>Analito</th><th>Cão</th><th>Gato</th><th>Unid.</th></tr></thead><tbody>'+LABREF.map(x=>'<tr><td>'+esc(x[1])+'</td><td>'+x[3].join("–")+'</td><td>'+x[4].join("–")+'</td><td>'+esc(x[2])+'</td></tr>').join("")+'</tbody></table></div>';
 return '<div class="stack"><h1>Interpretação laboratorial</h1>'+tabsBar("lab",tabs,arg)+body+'</div>'+disclaimer()}
function labSet(k,v){S.lab.v[k]=v===""?null:v;if(v==="")delete S.lab.v[k];saveMod("lab");labRun()}
function labEval(){const L=S.lab,sp=L.sp,V={};for(const [k,v] of Object.entries(L.v||{}))if(v!==""&&v!=null&&isFinite(num(v)))V[k]=num(v);
 const flags=[];for(const x of LABREF){if(V[x[0]]==null)continue;const r=sp==="cat"?x[4]:x[3],val=V[x[0]];if(val>r[1])flags.push({x,val,d:"↑",c:x[6]});else if(val<r[0])flags.push({x,val,d:"↓",c:x[7]})}
 const P=[],hi=k=>{const x=LABREF.find(y=>y[0]===k);return V[k]!=null&&V[k]>(sp==="cat"?x[4]:x[3])[1]},lo=k=>{const x=LABREF.find(y=>y[0]===k);return V[k]!=null&&V[k]<(sp==="cat"?x[4]:x[3])[0]};
 // azotemia
 if(hi("crea")||hi("ureia")){const u=V.usg,lim=sp==="cat"?1.035:1.030;if(u==null)P.push(["warn","Azotemia: meça a DENSIDADE URINÁRIA (antes da fluidoterapia) para classificar em pré-renal, renal ou pós-renal."]);
  else if(u>=lim)P.push(["info","Azotemia com urina concentrada (USG "+u.toFixed(3)+" ≥ "+lim.toFixed(3)+"): sugere AZOTEMIA PRÉ-RENAL (desidratação, hipovolemia, ICC) — reavaliar após reidratação. Excluir obstrução/uroabdome (pós-renal)."]);
  else if(u<=1.012&&u>=1.007)P.push(["bad","Azotemia com ISOSTENÚRIA (USG "+u.toFixed(3)+"): perda de capacidade de concentração — DOENÇA RENAL (aguda ou crônica). Estadiar pela IRIS após estabilização."]);
  else P.push(["warn","Azotemia com urina pouco concentrada (USG "+u.toFixed(3)+"): sugere componente RENAL (ou interferência de diuréticos, fluidos, corticoides, hipoadrenocorticismo, hipercalcemia, piometra). Estadiar pela IRIS se persistente."]);}
 if(hi("ureia")&&V.crea!=null&&!hi("crea"))P.push(["info","Ureia elevada com creatinina normal: considerar hemorragia gastrointestinal, dieta hiperproteica, desidratação leve ou catabolismo (corticoides, febre)."]);
 if(hi("sdma")&&V.crea!=null&&!hi("crea"))P.push(["warn","SDMA elevada com creatinina normal: redução precoce da TFG — repetir em 2–4 semanas; se persistente (> 14 µg/dL), considerar DRC IRIS 1 (ou 2 se ≥ 25 µg/dL). Em animais com baixa massa muscular a SDMA é mais confiável."]);
 // Na:K
 if(V.na!=null&&V.k!=null){const r=V.na/V.k;if(r<27)P.push(["bad","Relação Na:K = "+fmt(r,1)+" (< 27): SUSPEITAR DE HIPOADRENOCORTICISMO (Addison)"+(r<24?" — muito sugestiva":"")+". Triagem com cortisol basal: ≥ 2 µg/dL torna Addison improvável; < 2 µg/dL → confirmar com teste de estimulação com ACTH. Diferenciais: tricuríase, efusões repetidamente drenadas, LRA, obstrução uretral, uroabdome."]);
  else P.push(["ok","Relação Na:K = "+fmt(r,1)+" (≥ 27)."]);}
 if(hi("k")&&V.k>=6)P.push(["bad","HIPERCALEMIA ≥ 6 mEq/L: risco de arritmia (bradicardia, onda T apiculada, ausência de P). Fazer ECG; excluir obstrução uretral/uroabdome e Addison; tratar se ≥ 7,5 ou com alterações de ECG (gluconato de cálcio, insulina + glicose, salina)."]);
 if(lo("k")&&V.k<3)P.push(["bad","HIPOCALEMIA grave (< 3 mEq/L): fraqueza muscular, ventroflexão cervical (gatos), íleo. Suplementar KCl sem ultrapassar 0,5 mEq/kg/h (ver calculadora de KCl)."]);
 // leucograma
 if(hi("seg")&&lo("lin")&&!hi("bas"))P.push(["info","LEUCOGRAMA DE ESTRESSE (neutrofilia madura + linfopenia"+(lo("eos")?" + eosinopenia":"")+(hi("mon")&&sp==="dog"?" + monocitose":"")+"): corticoide endógeno/exógeno, dor, doença sistêmica."]);
 if(V.lin!=null&&!lo("lin")&&(lo("na")||(V.na&&V.k&&V.na/V.k<27)))P.push(["warn","Linfócitos normais/altos em paciente doente com alteração eletrolítica: AUSÊNCIA de leucograma de estresse reforça a suspeita de hipoadrenocorticismo."]);
 if(hi("bas")){const deg=V.seg!=null&&V.bas>V.seg;P.push([deg?"bad":"warn","DESVIO À ESQUERDA"+(deg?" DEGENERATIVO (bastonetes > segmentados): demanda tecidual supera a produção medular — inflamação/sepse grave (piometra, peritonite, pneumonia); mau prognóstico, agir rápido.":" REGENERATIVO: inflamação aguda com resposta medular adequada.")]);}
 if(lo("seg")&&V.seg<1)P.push(["bad","NEUTROPENIA GRAVE (< 1.000/µL): risco de sepse — isolamento, antibiótico de amplo espectro se febre; investigar parvovirose, FeLV/FIV, erliquiose, fármacos, imunomediada."]);
 if(hi("eos"))P.push(["info","Eosinofilia: parasitismo, alergia/atopia, asma felina, complexo granuloma eosinofílico, mastocitoma, hipoadrenocorticismo."]);
 // eritrograma
 if(lo("ht")){let t="ANEMIA (Ht "+V.ht+"%)";if(V.vcm!=null&&V.chcm!=null){if(lo("vcm")&&lo("chcm"))t+=" microcítica hipocrômica → deficiência de ferro (perda sanguínea crônica: pulgas, ancilóstomos, sangramento GI) ou shunt portossistêmico.";else if(hi("vcm")&&lo("chcm"))t+=" macrocítica hipocrômica → padrão REGENERATIVO (confirmar com reticulócitos > 60.000/µL cão; > 50.000/µL gato).";else if(!hi("vcm")&&!lo("vcm"))t+=" normocítica normocrômica → geralmente NÃO REGENERATIVA (doença crônica, DRC, medular) ou aguda/pré-regenerativa (< 3–5 dias)."}t+=" Use o assistente de anemia (Diagnósticos) e a contagem de reticulócitos.";P.push([V.ht<(sp==="cat"?15:20)?"bad":"warn",t])}
 if(hi("ht")&&hi("pt"))P.push(["info","Ht e proteínas totais elevados: DESIDRATAÇÃO (hemoconcentração)."]);
 if(hi("ht")&&V.pt!=null&&!hi("pt"))P.push(["info","Ht elevado com proteínas normais: contração esplênica (excitação) ou policitemia verdadeira/secundária (gastroenterite hemorrágica pode cursar com Ht alto e PT normal/baixa)."]);
 if(lo("ht")&&lo("pt"))P.push(["warn","Anemia com hipoproteinemia: sugere PERDA DE SANGUE (externa ou gastrointestinal)."]);
 if(lo("plq"))P.push([V.plq<50?"bad":"warn","Trombocitopenia"+(V.plq<50?" GRAVE (< 50.000/µL — risco de sangramento espontâneo; < 30.000 sugere PTI ou erliquiose)":"")+". "+(sp==="cat"?"Em gatos conferir agregados plaquetários no esfregaço (pseudotrombocitopenia).":"Investigar hemoparasitoses (Ehrlichia, Anaplasma — PCR/sorologia), CID, imunomediada.")]);
 // fígado
 if(hi("alt")&&hi("fa")){const a=V.alt/(sp==="cat"?80:100),f=V.fa/(sp==="cat"?80:156);P.push(["info","Elevação de ALT e FA — padrão predominantemente "+(a>f?"HEPATOCELULAR (ALT ↑ mais que FA): hepatite, toxinas, hipóxia, lipidose.":"COLESTÁTICO/INDUZIDO (FA ↑ mais que ALT): colestase, corticoides/hiperadrenocorticismo (cães), colangite.")+" Avaliar bilirrubina, ácidos biliares e ultrassom."])}
 else if(hi("fa")&&!hi("alt"))P.push(["info",sp==="cat"?"FA elevada em gato (isoladamente é SIGNIFICATIVA): lipidose hepática, colangite, hipertireoidismo (dosar T4 total em gatos > 7 anos), diabetes.":"FA elevada isolada em cão: indução por corticoides/fenobarbital, hiperadrenocorticismo, colestase, crescimento ósseo (filhote), osteossarcoma, hiperplasia nodular (idosos)."]);
 if(hi("bil")&&V.ht!=null)P.push([lo("ht")?"warn":"info",lo("ht")?"Hiperbilirrubinemia + anemia: considerar ICTERÍCIA PRÉ-HEPÁTICA (hemólise — anemia hemolítica imunomediada, Mycoplasma, Babesia, toxinas: cebola, zinco, paracetamol em gatos).":"Hiperbilirrubinemia com Ht normal: causa HEPÁTICA ou PÓS-HEPÁTICA (obstrução biliar, mucocele, pancreatite) — ultrassom abdominal."]);
 // proteínas
 if(V.alb!=null&&V.glob!=null){const ag=V.alb/V.glob;P.push([sp==="cat"&&ag<0.4?"warn":"info","Relação albumina:globulina = "+fmt(ag,2)+(sp==="cat"?(ag<0.4?" (< 0,4): aumenta a probabilidade de PIF em gato com sinais compatíveis (não é diagnóstica isoladamente).":ag>0.8?" (> 0,8): torna a PIF improvável.":" (0,4–0,8): inconclusiva para PIF."):(ag<0.6?" — baixa: hiperglobulinemia (inflamação crônica, erliquiose, leishmaniose) e/ou hipoalbuminemia.":""))])}
 if(lo("alb")&&V.alb<1.5)P.push(["bad","Hipoalbuminemia grave (< 1,5 g/dL): risco de efusões/edema. Investigar perda renal (UPC), intestinal (enteropatia perdedora de proteína) ou insuficiência hepática."]);
 if(lo("alb")&&hi("upc"))P.push(["warn","Hipoalbuminemia + proteinúria (UPC elevada): nefropatia perdedora de proteína (glomerulopatia) — avaliar pressão arterial, leishmaniose/erliquiose; risco tromboembólico (considerar antiagregante)."]);
 if(hi("upc"))P.push(["warn","Proteinúria (UPC "+V.upc+"): só interpretar com sedimento inativo (sem ITU/hematúria). "+(sp==="cat"?"Gato: 0,2–0,4 limítrofe; > 0,4 proteinúrico (IRIS).":"Cão: 0,2–0,5 limítrofe; > 0,5 proteinúrico; > 2 sugere glomerulopatia (IRIS).")]);
 // glicose
 if(hi("glic")){const g=V.glic;if(sp==="cat"&&g<=300)P.push(["info","Hiperglicemia em gato até ~300 mg/dL pode ser de ESTRESSE — dosar frutosamina para diferenciar de diabetes."]);else if(g>(sp==="cat"?280:180))P.push(["warn","Glicemia acima do limiar renal ("+(sp==="cat"?"~280":"~180")+" mg/dL) — esperar glicosúria. Diabetes mellitus provável se persistente; pesquisar CETONAS (cetoacidose = emergência)."])}
 if(lo("glic")&&V.glic<60)P.push(["bad","HIPOGLICEMIA (< 60 mg/dL): dextrose 0,5–1 mL/kg de glicose 50% diluída 1:2–1:4 IV. Investigar sepse, insulinoma, xilitol, filhote toy, hipoadrenocorticismo, insuficiência hepática; excluir ARTEFATO (sangue não centrifugado)."]);
 // cálcio/fósforo
 if(hi("ca"))P.push(["warn","Hipercalcemia: mnemônico GOSH DARN IT — granulomatosa, osteolítica, espúria, hiperparatireoidismo, D (vitamina D/rodenticida colecalciferol), Addison, renal, neoplasia (LINFOMA, adenocarcinoma de saco anal), idiopática (gatos), temperatura. Confirmar com cálcio IONIZADO; examinar linfonodos e saco anal."]);
 if(lo("ca")&&V.ca<7)P.push(["bad","Hipocalcemia (< 7 mg/dL): em cadela lactante = ECLÂMPSIA (tetania). Gluconato de cálcio 10% 0,5–1,5 mL/kg IV lento com ECG. Corrigir pelo cálcio ionizado se hipoalbuminemia."]);
 if(V.ca!=null&&V.p!=null&&V.ca*V.p>70)P.push(["warn","Produto Ca × P = "+fmt(V.ca*V.p,0)+" (> 70): risco de mineralização de tecidos moles (DRC) — dieta renal/quelante de fósforo."]);
 if(hi("col")&&hi("fa")&&sp==="dog")P.push(["info","Hipercolesterolemia + FA alta em cão: considerar hiperadrenocorticismo, hipotireoidismo, diabetes ou colestase."]);
 // urina
 if(V.usg!=null&&V.usg<1.008)P.push(["warn","HIPOSTENÚRIA (USG < 1,008): rins diluindo ativamente — diabetes insípido, polidipsia psicogênica, hiperadrenocorticismo, piometra, hipercalcemia, insuficiência hepática."]);
 return {flags,P,V}}
function labRun(){const o=document.getElementById("labOut");if(!o)return;const {flags,P}=labEval();
 if(!flags.length&&!P.length){o.innerHTML='<div class="sm muted">Digite os resultados para ver alterações, causas prováveis e padrões.</div>';return}
 o.innerHTML=(P.length?'<div class="lbl">Interpretação / padrões</div><div class="stack" style="margin:6px 0 12px">'+P.map(([c,t])=>'<div class="note '+c+'">'+esc(t)+'</div>').join("")+'</div>':"")+
 (flags.length?'<div class="lbl">Alterações ('+flags.length+')</div><div class="stack" style="margin-top:6px">'+flags.map(f=>'<div class="sm"><b>'+f.d+' '+esc(f.x[1])+': '+f.val+' '+esc(f.x[2])+'</b><br/><span class="muted">'+esc(f.c)+'</span></div>').join("")+'</div>':'<div class="note ok">Todos os valores informados dentro da faixa de referência.</div>')}
function labText(){const {flags,P}=labEval();return "INTERPRETAÇÃO LABORATORIAL ("+(S.lab.sp==="cat"?"Gato":"Cão")+")\n\nAlterações:\n"+(flags.map(f=>"- "+f.d+" "+f.x[1]+": "+f.val+" "+f.x[2]).join("\n")||"- nenhuma")+"\n\nPadrões:\n"+(P.map(p=>"- "+p[1]).join("\n")||"- nenhum")}
function gasEval(G){const sp=G.sp||"dog",N=sp==="cat"?{pco2:31,hco3:18,na:156,cl:120,ag:[13,27]}:{pco2:37,hco3:22,na:146,cl:110,ag:[12,24]};
 const v=k=>G[k]===""||G[k]==null?null:num(G[k]);const ph=v("ph"),pc=v("pco2"),hc=v("hco3");const R=[];let prim="";
 if(ph==null||pc==null||hc==null)return{R:[["info","Informe pH, pCO₂ e HCO₃⁻ para a análise ácido-base."]],prim:""};
 if(ph<7.35){if(hc<N.hco3-2&&(pc<=N.pco2+3||hc/N.hco3<pc/N.pco2))prim="Acidose metabólica";else if(pc>N.pco2+3)prim="Acidose respiratória";else prim="Acidose metabólica"}
 else if(ph>7.45){if(hc>N.hco3+2&&!(pc<N.pco2-3&&pc/N.pco2<hc/N.hco3))prim="Alcalose metabólica";else if(pc<N.pco2-3)prim="Alcalose respiratória";else prim="Alcalose metabólica"}
 else{if(Math.abs(hc-N.hco3)>3||Math.abs(pc-N.pco2)>4)prim="pH normal com HCO₃⁻/pCO₂ alterados — distúrbio MISTO compensado ou duplo";else prim="Equilíbrio ácido-base normal"}
 const dH=hc-N.hco3,dP=pc-N.pco2;let exp=null,lab="";
 if(prim==="Acidose metabólica"){exp=N.pco2+0.7*dH;lab="pCO₂ esperada"}
 else if(prim==="Alcalose metabólica"){exp=N.pco2+0.7*dH;lab="pCO₂ esperada"}
 else if(prim==="Acidose respiratória"){exp=N.hco3+(G.cr==="c"?0.35:0.15)*dP;lab="HCO₃⁻ esperado ("+(G.cr==="c"?"crônica":"aguda")+")"}
 else if(prim==="Alcalose respiratória"){exp=N.hco3+(G.cr==="c"?0.55:0.25)*dP;lab="HCO₃⁻ esperado ("+(G.cr==="c"?"crônica":"aguda")+")"}
 R.push([/normal$/.test(prim)?"ok":"warn","Distúrbio primário: "+prim.toUpperCase()+" (pH "+ph+")."]);
 if(exp!=null){const resp=/metab/.test(prim);const obs=resp?pc:hc;const ok=Math.abs(obs-exp)<=(resp?3:2);
  R.push([ok?"ok":"bad",lab+": "+fmt(exp,1)+" ± "+(resp?3:2)+" — medida "+obs+". "+(ok?"Compensação ADEQUADA (distúrbio simples).":resp?(obs>exp?"pCO₂ acima do esperado → ACIDOSE RESPIRATÓRIA concomitante (hipoventilação).":"pCO₂ abaixo do esperado → ALCALOSE RESPIRATÓRIA concomitante (hiperventilação, dor, sepse)."):(obs>exp?"HCO₃⁻ acima do esperado → ALCALOSE METABÓLICA concomitante.":"HCO₃⁻ abaixo do esperado → ACIDOSE METABÓLICA concomitante."))+(sp==="cat"&&resp?" (Gatos: compensação respiratória menos previsível.)":"")])}
 const na=v("na"),k=v("k"),cl=v("cl"),alb=v("alb"),lac=v("lac");
 if(na!=null&&cl!=null){const ag=na+(k||0)-(cl+hc);const agc=alb!=null?ag+4.2*(3.7-alb):null;const hiag=(agc!=null?agc:ag)>N.ag[1];
  R.push([hiag?"bad":"info","Ânion gap = (Na + K) − (Cl + HCO₃) = "+fmt(ag,1)+" mEq/L (ref. "+N.ag.join("–")+")"+(agc!=null?" · corrigido pela albumina ≈ "+fmt(agc,1)+" (fórmula canina de Constable)":"")+". "+(prim==="Acidose metabólica"||dH<-3?(hiag?"Acidose metabólica com ÂNION GAP ALTO (normoclorêmica): lactato (hipoperfusão), cetoácidos (cetoacidose diabética), uremia, toxinas (ETILENOGLICOL, salicilatos, metaldeído).":"Acidose metabólica com ânion gap NORMAL (hiperclorêmica): diarreia (perda de HCO₃⁻), acidose tubular renal, salina 0,9% em excesso, hipoadrenocorticismo."):(hiag?"Ânion gap alto sem acidemia evidente: considerar distúrbio MISTO (acidose com AG alto + alcalose metabólica, ex.: vômito + uremia/cetoacidose).":"Dentro da referência. Lembre: hipoalbuminemia reduz o AG e pode mascarar ânions não medidos."))]);
  const clc=cl*N.na/na;R.push([Math.abs(clc-N.cl)>4?"warn":"ok","Cloreto corrigido pelo sódio = "+fmt(clc,1)+" mEq/L (normal ~"+N.cl+"). "+(clc<N.cl-4?"HIPOCLOREMIA corrigida → alcalose hipoclorêmica (vômito de conteúdo gástrico, obstrução pilórica, furosemida): repor com NaCl 0,9% + KCl.":clc>N.cl+4?"HIPERCLOREMIA corrigida → acidose hiperclorêmica (diarreia, salina em excesso, ATR).":"Normal.")])}
 if(lac!=null)R.push([lac>4?"bad":lac>2.5?"warn":"ok","Lactato "+lac+" mmol/L: "+(lac>4?"HIPERLACTATEMIA importante — hipoperfusão/sepse/DVG (lactato > 6 em DVG associado a necrose gástrica); reavaliar após fluidoterapia (queda > 50% em 12 h = bom prognóstico).":lac>2.5?"hiperlactatemia leve — avaliar perfusão.":"normal (< 2,5).")]);
 return{R,prim}}
function gasRun(){const o=document.getElementById("gasOut");if(!o)return;const {R}=gasEval(S.gaso);o.innerHTML='<div class="stack">'+R.map(([c,t])=>'<div class="note '+c+'">'+esc(t)+'</div>').join("")+'</div>'}

/* ---------- 2. Documentos, termos e prontuário (Res. CFMV 1.321/2020) ---------- */
const DOCS=[["ficha","Ficha clínica (anamnese + exame físico)"],["saude","Atestado de saúde"],["vacina","Atestado de vacinação"],["obito","Atestado de óbito"],["t-anest","Termo — anestesia/sedação"],["t-cir","Termo — procedimento cirúrgico"],["t-int","Termo — internação"],["t-eut","Termo — eutanásia"],["t-recusa","Termo — recusa/alta a pedido"],["posop","Orientações pós-operatórias"],["obito-orient","Orientações sobre o corpo (destinação)"]];
function docPat(){const P=S.dc;return "Paciente: "+(P.pn||"________")+" | Espécie: "+(P.psp||"____")+" | Raça: "+(P.pr||"____")+" | Sexo: "+(P.ps||"___")+" | Idade: "+(P.pi||"___")+" | Pelagem: "+(P.pp||"____")+(P.pm?" | Microchip: "+P.pm:"")+" | Peso: "+(P.pw||"___")+" kg"}
function docTut(){const P=S.dc;return "Tutor(a)/responsável: "+(P.tn||"______________________")+" | CPF/RG: "+(P.tc||"______________")+"\nEndereço: "+(P.te||"______________________________")+" | Telefone: "+(P.tt||"____________")}
function docBody(t){const P=S.dc,D=S.doc,hoje=dBR(new Date()),mv=(D.nome||"__________________")+" — CRMV "+(D.crmv||"______"),proc=P.proc||"__________________________";
 const ident=docPat()+"\n"+docTut()+"\n\n";
 const termoBase=(titulo,txt)=>titulo+"\n\n"+ident+txt+"\n\nDeclaro ter sido esclarecido(a) de forma clara sobre os riscos, benefícios, alternativas e custos estimados, ter tido a oportunidade de fazer perguntas e que todas foram respondidas. Autorizo, de forma livre e esclarecida, o(a) médico(a)-veterinário(a) "+mv+" e sua equipe a realizar o(s) procedimento(s) descrito(s), bem como as medidas de emergência que se fizerem necessárias.\n\nLocal e data: "+(D.end?D.end.split(",").slice(-1)[0].trim()+", ":"")+hoje+"\n\n_________________________________\nAssinatura do(a) tutor(a)/responsável\n\n_________________________________\n"+mv;
 switch(t){
 case "ficha":return "FICHA CLÍNICA — PRONTUÁRIO\nData: "+hoje+"\n\n"+ident+"ANAMNESE\nQueixa principal: "+(P.qp||"")+"\nHistórico / evolução: "+(P.hist||"")+"\nAlimentação: ______  Água: ______  Ambiente/contactantes: ______\nVacinação/vermifugação/ectoparasiticida: ______\nMedicações em uso: ______  Doenças/cirurgias prévias: ______\nApetite ( ) normal ( ) reduzido ( ) ausente  Vômito ( )  Diarreia ( )  Tosse ( )  Espirros ( )\nUrina: ______  Fezes: ______  Reprodutivo (cio, prenhez, castração): ______\n\nEXAME FÍSICO\nEstado geral/consciência: ______  Escore corporal (1–9): ___  Escore de dor: ___\nFC: ___ bpm  FR: ___ mpm  T: ___ °C  TPC: ___ s  Mucosas: ______  Hidratação: ___%\nPulso: ______  Linfonodos: ______  Auscultação cardíaca/pulmonar: ______\nPalpação abdominal: ______  Pele/pelame/ouvidos: ______  Olhos: ______  Boca/dentes: ______\nSistema musculoesquelético/neurológico: ______\n\nSUSPEITAS / DIAGNÓSTICOS DIFERENCIAIS: "+(P.ddx||"")+"\nEXAMES SOLICITADOS: ______\nCONDUTA / PRESCRIÇÃO: "+(P.cond||"")+"\nRETORNO: ______\n\n_________________________________\n"+mv+"\n\n(Prontuário: manter guardado por no mínimo 5 anos — Res. CFMV 1.321/2020.)";
 case "saude":return "ATESTADO DE SAÚDE\n\nAtesto, para os devidos fins"+(P.fin?" ("+P.fin+")":"")+", que examinei nesta data o animal abaixo identificado e que o mesmo se encontra CLINICAMENTE SADIO, sem sinais clínicos de doenças infectocontagiosas e/ou parasitárias, apto"+(P.fin?" para "+P.fin:" para trânsito/viagem")+".\n\n"+ident+"Vacinação antirrábica: "+(P.vac||"__________ (data / laboratório / partida)")+"\n\nEste atestado tem validade de ____ dias (verifique a exigência da empresa de transporte/destino).\n\n"+hoje+"\n\n_________________________________\n"+mv;
 case "vacina":return "ATESTADO DE VACINAÇÃO\n\nAtesto que o animal abaixo identificado foi vacinado por mim, conforme descrito:\n\n"+ident+"Vacina(s) aplicada(s) — nome comercial, laboratório, partida/lote, fabricação/validade, data:\n"+(P.vac||"__________________________________________")+"\n\nPróxima dose: "+(P.prox||"__________")+"\n\n"+hoje+"\n\n_________________________________\n"+mv;
 case "obito":return "ATESTADO DE ÓBITO\n\n"+ident+"Data e hora do óbito: "+(P.dh||"__________")+"\nLocal: "+(P.loc||"__________")+"\nCausa(s) da morte (provável/confirmada): "+(P.causa||"__________________________")+"\nForma do óbito: ( ) natural ( ) eutanásia ( ) acidente/trauma ( ) a esclarecer\nNecropsia: ( ) realizada ( ) não realizada ( ) recusada pelo tutor\nSuspeita de doença de notificação obrigatória/zoonose: ( ) não ( ) sim: ______\nDestinação do corpo: "+(P.dest||"( ) cremação ( ) sepultamento ( ) recolhimento por empresa licenciada ( ) entregue ao tutor")+"\n\n"+hoje+"\n\n_________________________________\n"+mv;
 case "t-anest":return termoBase("TERMO DE CONSENTIMENTO LIVRE E ESCLARECIDO PARA ANESTESIA/SEDAÇÃO","Procedimento: "+proc+"\nProtocolo/tipo: ( ) sedação ( ) anestesia geral inalatória ( ) anestesia injetável ( ) anestesia locorregional\nClassificação de risco anestésico (ASA): "+(P.asa||"___")+"\n\nFui informado(a) de que todo procedimento anestésico envolve riscos, inclusive de complicações cardiorrespiratórias, reações a fármacos e ÓBITO, mesmo com todos os cuidados, monitoração e exames prévios; que o jejum indicado deve ser respeitado; e que a omissão de informações sobre a saúde do animal pode aumentar o risco.");
 case "t-cir":return termoBase("TERMO DE CONSENTIMENTO LIVRE E ESCLARECIDO PARA PROCEDIMENTO CIRÚRGICO","Procedimento cirúrgico: "+proc+"\n\nFui informado(a) sobre o diagnóstico, a indicação, a técnica, os riscos (anestésicos, hemorragia, infecção, deiscência, recidiva, complicações pós-operatórias e óbito), as alternativas terapêuticas e os cuidados pós-operatórios necessários, e que podem ser necessárias alterações do plano durante o procedimento em benefício do paciente.");
 case "t-int":return termoBase("TERMO DE CONSENTIMENTO PARA INTERNAÇÃO","Motivo da internação: "+proc+"\nPrevisão de custo diário estimado: R$ ________\n\nFui informado(a) sobre o estado clínico, o prognóstico, o plano terapêutico e os riscos inerentes à doença e ao tratamento, sobre as normas e horários de visita e boletins, e que serei comunicado(a) em caso de intercorrências. Comprometo-me a manter meus contatos atualizados.");
 case "t-eut":return "TERMO DE CONSENTIMENTO PARA REALIZAÇÃO DE EUTANÁSIA\n\n"+ident+"Motivo/indicação clínica: "+(P.causa||proc)+"\n\nDeclaro que fui informado(a) de maneira clara sobre o diagnóstico, o prognóstico e as alternativas terapêuticas, e que, de forma livre e esclarecida, AUTORIZO a realização da eutanásia do animal acima identificado pelo(a) médico(a)-veterinário(a) "+mv+", por método humanitário aceito pelo CFMV (Res. CFMV nº 1.000/2012 e atualizações), com sedação/anestesia prévia. Declaro ser o(a) responsável legal pelo animal.\n\nDestinação do corpo: "+(P.dest||"( ) cremação individual ( ) cremação coletiva ( ) recolhimento por empresa licenciada ( ) entregue ao tutor")+"\nDeseja estar presente: ( ) sim ( ) não\n\nLocal e data: "+hoje+"\n\n_________________________________\nAssinatura do(a) tutor(a)/responsável\n\n_________________________________\nTestemunha\n\n_________________________________\n"+mv;
 case "t-recusa":return "TERMO DE RECUSA DE PROCEDIMENTO / ALTA A PEDIDO\n\n"+ident+"Procedimento/conduta recomendada e não autorizada: "+proc+"\n\nDeclaro que fui informado(a) pelo(a) médico(a)-veterinário(a) "+mv+" sobre a necessidade do(s) procedimento(s) acima, dos riscos decorrentes da recusa — incluindo agravamento do quadro e óbito — e, ainda assim, por decisão própria, NÃO AUTORIZO sua realização / solicito a alta do paciente, assumindo integral responsabilidade pelas consequências.\n\n"+hoje+"\n\n_________________________________\nAssinatura do(a) tutor(a)/responsável\n\n_________________________________\n"+mv;
 case "posop":return "ORIENTAÇÕES PÓS-OPERATÓRIAS\n\n"+docPat()+"\nProcedimento realizado: "+proc+" — "+hoje+"\n\n1. Manter o animal em local limpo, seco, aquecido e tranquilo nas primeiras 24–48 h; restringir atividade (sem pular, correr ou subir escadas) por ____ dias.\n2. Usar colar elizabetano ou roupa cirúrgica CONTINUAMENTE até a retirada dos pontos — não permitir que lamba/morda a ferida.\n3. Alimentação: oferecer água após ____ h e pequena porção de alimento após ____ h; normalizar no dia seguinte se não houver vômito.\n4. Limpeza da ferida: ____x ao dia com soro fisiológico e gaze; não usar produtos caseiros sem orientação.\n5. Medicações conforme a receita, nos horários indicados, até o fim do tratamento.\n6. Retirada de pontos: em ____ dias (data prevista: ________).\n7. PROCURE ATENDIMENTO IMEDIATO se observar: sangramento ativo, ferida aberta, inchaço, secreção ou mau cheiro, apatia intensa, gengivas pálidas, vômitos repetidos, recusa de água por > 24 h, dificuldade para respirar ou para urinar, dor intensa.\n\nContato da clínica: "+(D.tel||"____________")+"\n\n_________________________________\n"+mv;
 case "obito-orient":return "ORIENTAÇÕES SOBRE A DESTINAÇÃO DO CORPO DO ANIMAL\n\n"+docPat()+"\n\n• O corpo do animal é resíduo de serviço de saúde (Grupo A) quando o óbito ocorre em estabelecimento veterinário (RDC ANVISA 222/2018 / CONAMA 358/2005) e deve ser encaminhado a empresa licenciada (cremação ou aterro sanitário licenciado), salvo opção do tutor por cremação individual/cemitério de animais.\n• Sepultamento em quintal/terreno particular é regulado por normas municipais e ambientais — consulte a legislação local; nunca em áreas próximas a nascentes/poços.\n• Suspeita de raiva ou outra zoonose: o corpo NÃO deve ser entregue — encaminhar amostras ao serviço oficial conforme protocolo.\n\n"+hoje+"\n\n_________________________________\n"+mv}}
function vDocs(arg){arg=arg||"ficha";loadMod("dc",{});const R=S.rx||{},P=R.pat||{},T=R.tut||{};const d=S.dc;
 if(!d._init){Object.assign(d,{pn:P.nome||"",psp:P.sp||"",pr:P.raca||"",ps:P.sexo||"",pi:P.idade||"",pw:P.peso||"",tn:T.nome||"",tc:T.cpf||"",te:T.end||"",tt:T.tel||"",_init:1});saveMod("dc")}
 const extra={ficha:[["qp","Queixa principal"],["hist","Histórico",1],["ddx","Suspeitas/diferenciais"],["cond","Conduta",1]],saude:[["fin","Finalidade (ex.: viagem aérea, trânsito interestadual)"],["vac","Vacinação antirrábica (data/lab./partida)"]],vacina:[["vac","Vacinas aplicadas (nome, laboratório, partida, validade, data)",1],["prox","Próxima dose"]],obito:[["dh","Data e hora"],["loc","Local"],["causa","Causa da morte"],["dest","Destinação do corpo"]],"t-anest":[["proc","Procedimento"],["asa","ASA"]],"t-cir":[["proc","Procedimento cirúrgico"]],"t-int":[["proc","Motivo da internação"]],"t-eut":[["causa","Indicação clínica"],["dest","Destinação do corpo"]],"t-recusa":[["proc","Procedimento recusado"]],posop:[["proc","Procedimento realizado"]],"obito-orient":[]}[arg]||[];
 return '<div class="stack"><h1>Documentos & termos</h1><p class="muted sm" style="margin:0">Modelos baseados na Res. CFMV nº 1.321/2020 (documentos na clínica médico-veterinária). Os dados do paciente/tutor vêm da receita e podem ser editados. Revise o texto antes de imprimir.</p>'+
 '<div class="card">'+selF("docT","Documento",DOCS,arg,"location.hash='#/docs/'+this.value")+'</div>'+
 '<div class="card"><h3>Paciente e tutor</h3><div class="grid g2m" style="margin-top:8px">'+[["pn","Nome do animal"],["psp","Espécie"],["pr","Raça"],["ps","Sexo"],["pi","Idade"],["pp","Pelagem"],["pm","Microchip"],["pw","Peso (kg)"],["tn","Tutor(a)"],["tc","CPF/RG"],["te","Endereço"],["tt","Telefone"]].map(([k,l])=>txtF("dc",k,l)).join("")+'</div></div>'+
 (extra.length?'<div class="card"><h3>Dados do documento</h3><div class="stack" style="margin-top:8px">'+extra.map(([k,l,a])=>txtF("dc",k,l,"",a)).join("")+'</div></div>':"")+
 (S.doc.nome?"":'<div class="note warn">Preencha seu nome, CRMV e clínica em <a href="#/ajustes">Ajustes</a> para sair no cabeçalho e na assinatura.</div>')+
 '<div class="actions"><button class="btn pri" onclick="docPrint(\''+arg+'\')">'+ic("print",18)+' Imprimir / PDF</button><button class="btn" onclick="copy(docBody(\''+arg+'\'))">'+ic("copy",18)+' Copiar texto</button><button class="btn" onclick="if(confirm(\'Limpar os dados do documento?\')){S.dc={_init:1};saveMod(\'dc\');rerender()}">'+ic("trash",18)+' Limpar</button></div>'+
 '<div class="card"><h3>Pré-visualização</h3><pre class="sm" style="white-space:pre-wrap;font-family:inherit;margin:8px 0 0">'+esc(docBody(arg))+'</pre></div></div>'}
function docPrint(t){const txt=docBody(t);printBlock("Documento",'<pre style="white-space:pre-wrap;font-family:Georgia,serif;font-size:13.5px;line-height:1.6">'+esc(txt)+'</pre>',(DOCS.find(x=>x[0]===t)||["","Documento"])[1])}

/* ---------- 3. Vacinação e prevenção ---------- */
function vVac(arg){arg=arg||"dog";const V=VACS[arg]||VACS.dog;const C=loadMod("vacc",{sp:"dog",nasc:"",risco:"n"});
 const rows=l=>'<div class="scroll-x"><table class="tbl"><thead><tr><th>Vacina</th><th>Protocolo inicial</th><th>Reforço</th></tr></thead><tbody>'+l.map(r=>'<tr><td><b>'+esc(r[0])+'</b></td><td>'+esc(r[1])+'</td><td>'+esc(r[2])+'</td></tr>').join("")+'</tbody></table></div>';
 return '<div class="stack"><h1>Vacinação & prevenção</h1>'+tabsBar("vacinas",Object.keys(VACS).map(k=>[k,VACS[k].n]).concat([["cal","Gerar calendário"]]),arg)+
 (arg==="cal"?vVacCal(C):'<div class="card"><h3>Essenciais (core)</h3>'+rows(V.core)+'</div><div class="card"><h3>Não essenciais (conforme risco)</h3>'+rows(V.noncore)+'</div><div class="card"><h3>Vermifugação e parasitas</h3><p class="sm" style="margin:6px 0 0">'+esc(V.verm)+'</p></div>'+
 '<p class="xs muted">Base: diretrizes WSAVA 2024 (cães e gatos), AAEP (equinos) e PNCEBT/MAPA (bovinos). Siga também a bula do produto registrado no MAPA e a legislação local (antirrábica).</p>')+'</div>'+disclaimer()}
function vacSchedule(C){const n=parseDate(C.nasc);if(!n)return[];const sp=C.sp,L=[],w=x=>addDays(n,x*7);
 const poli=sp==="cat"?"Polivalente felina (tríplice/quádrupla)":"Polivalente (V8/V10)";
 [6,9,12,16].forEach((x,i)=>L.push([w(x),poli+" — "+(i+1)+"ª dose"]));
 L.push([w(12),"Antirrábica — 1ª dose"]);
 if(sp==="dog"){if(C.risco==="s"){L.push([w(10),"Traqueobronquite (intranasal/oral)"])}}
 if(sp==="cat"&&C.risco==="s"){L.push([w(9),"Testar FeLV/FIV"]);L.push([w(10),"FeLV — 1ª dose"]);L.push([w(14),"FeLV — 2ª dose"])}
 L.push([w(26),poli+" — reforço (6 meses, WSAVA)"]);L.push([w(64),"Antirrábica — reforço anual"]);L.push([w(64),poli+" — reforço anual (ou trienal conforme risco/produto)"]);
 [2,4,6,8].forEach(x=>L.push([w(x),"Vermífugo (filhote)"]));[12,16,20,24].forEach(x=>L.push([w(x),"Vermífugo (mensal até 6 meses)"]));
 return L.filter(x=>x[0]>=addDays(n,7)).sort((a,b)=>a[0]-b[0])}
function vVacCal(C){const L=vacSchedule(C),hoje=new Date();
 return '<div class="card grid g2m">'+selF("vcSp","Espécie",[["dog","Cão"],["cat","Gato"]],C.sp,"S.vacc.sp=this.value;saveMod('vacc');rerender()")+'<div class="field"><label>Data de nascimento</label><input class="inp" type="date" value="'+esc(C.nasc)+'" onchange="S.vacc.nasc=this.value;saveMod(\'vacc\');rerender()" /></div>'+selF("vcR","Alto risco (rua, hotel, gatil, contactantes)?",[["n","Não"],["s","Sim"]],C.risco,"S.vacc.risco=this.value;saveMod('vacc');rerender()")+'</div>'+
 (L.length?'<div class="out"><div class="lbl">Calendário sugerido</div><div class="scroll-x"><table class="tbl" style="margin-top:6px"><tbody>'+L.map(([d,t])=>'<tr style="'+(d<hoje?"opacity:.55":"")+'"><td style="white-space:nowrap"><b>'+dBR(d)+'</b></td><td>'+esc(t)+(d<hoje?' <span class="xs muted">(data passada — aplicar o quanto antes se não feita)</span>':"")+'</td></tr>').join("")+'</tbody></table></div><div class="note info" style="margin-top:10px">Se o animal começou depois de 16 semanas: 2 doses da polivalente com 2–4 semanas de intervalo. A última dose da série do filhote deve ser ≥ 16 semanas de idade. Leptospirose: 2 doses iniciais e reforço anual (na V10).</div></div><div class="actions"><button class="btn pri" onclick="vacPrint()">'+ic("print",18)+' Imprimir carteira</button><button class="btn" onclick="copy(vacText())">'+ic("copy",18)+' Copiar</button></div>':'<div class="empty">Informe a data de nascimento.</div>')}
function vacText(){return "CALENDÁRIO DE VACINAÇÃO E VERMIFUGAÇÃO — "+(S.vacc.sp==="cat"?"Gato":"Cão")+"\nNascimento: "+dBR(parseDate(S.vacc.nasc))+"\n\n"+vacSchedule(S.vacc).map(([d,t])=>dBR(d)+" — "+t+"   [  ] aplicada").join("\n")}
function vacPrint(){printBlock("Carteira de vacinação",'<p><b>Paciente:</b> '+esc((S.rx.pat||{}).nome||"______________")+' &nbsp; <b>Tutor:</b> '+esc((S.rx.tut||{}).nome||"______________")+'</p><table style="width:100%;border-collapse:collapse;font-size:13px">'+'<tr><th style="border:1px solid #999;padding:4px">Data prevista</th><th style="border:1px solid #999;padding:4px">Vacina / vermífugo</th><th style="border:1px solid #999;padding:4px">Aplicada em / lote / assinatura</th></tr>'+vacSchedule(S.vacc).map(([d,t])=>'<tr><td style="border:1px solid #999;padding:6px">'+dBR(d)+'</td><td style="border:1px solid #999;padding:6px">'+esc(t)+'</td><td style="border:1px solid #999;padding:6px"></td></tr>').join("")+'</table>',"Carteira de vacinacao")}

/* ---------- 4. Reprodução ---------- */
const P4=[[0,2,"Basal (anestro/proestro inicial)","Repetir a cada 2–3 dias a partir do 5º dia de proestro."],[2,3,"Pico de LH provável (dia 0)","Ovulação em ~2 dias. Repetir em 24–48 h para confirmar a subida."],[3,5,"Pós-LH, pré-ovulação","Ovulação iminente (24–48 h)."],[5,10,"OVULAÇÃO (~dia 2 após LH)","Oócitos maturam em 2–3 dias: período fértil = dias 4 a 6 após o LH. Monta natural/sêmen fresco: dias 2 e 4 após o LH."],[10,25,"Pós-ovulação — período fértil","Sêmen refrigerado: inseminar agora (dias 4–5 após LH). Sêmen CONGELADO: inseminação intrauterina dias 5–6 após o LH."],[25,999,"Final do período fértil / diestro","Fertilidade declinando. Gestação: parto ~63 dias após o pico de LH."]];
const DIST=[["Contrações abdominais fortes e persistentes por > 30–60 min sem nascimento","Obstrução provável — exame vaginal digital, radiografia/US; cesariana se obstrução."],["> 2–4 h entre filhotes, com fetos remanescentes","Inércia uterina secundária ou obstrução."],["Secreção vaginal VERDE-escura sem nascimento em 2–4 h","Descolamento placentário (cadela) — feto em sofrimento."],["Temperatura caiu (< 37,5 °C) há > 24 h sem início do parto","Inércia uterina primária."],["Gestação prolongada: > 70–72 dias da cobertura (cão) / > 66 dias do pico de LH","Avaliar viabilidade fetal (US) — cesariana eletiva."],["Frequência cardíaca fetal < 180 bpm (sofrimento) ou < 150–160 bpm","< 150 bpm: cesariana IMEDIATA (normal 180–240 bpm)."],["Filhote/feto visível ou preso no canal por > 15 min","Tração delicada com lubrificação; episiotomia/cesariana."],["Mãe com sinais sistêmicos (choque, fraqueza, tremores, sangramento intenso)","Estabilizar (fluidos, cálcio se hipocalcemia, glicose) e cesariana."]];
function vRepro(arg){arg=arg||"parto";const R=loadMod("rep",{sp:"dog",dt:"",ref:"cob",p4:""});let body="";
 if(arg==="parto"){const g=GESTS[R.sp]||GESTS.dog,d=parseDate(R.dt);let out="";
  if(d){const base=R.sp==="dog"&&R.ref==="lh"?63:g[1];const pp=addDays(d,base),lo=addDays(d,R.sp==="dog"&&R.ref==="lh"?62:g[2][0]),hi=addDays(d,R.sp==="dog"&&R.ref==="lh"?64:g[2][1]);const dias=Math.round((new Date()-d)/864e5);
   out='<div class="lbl">Data provável do parto</div><div class="big">'+dBR(pp)+'</div><div class="sm">Janela: '+dBR(lo)+' a '+dBR(hi)+' · hoje = dia '+dias+' de gestação'+(dias>=0&&dias<=g[2][1]?" ("+Math.round(dias/base*100)+"%)":"")+'</div>'+
   (R.sp==="dog"&&R.ref==="cob"?'<div class="note warn" style="margin-top:10px">A partir da cobertura a precisão é baixa (57–72 dias), pois os espermatozoides sobrevivem até 7 dias. Para previsão de ± 1 dia use a data do pico de LH (progesterona) ou ultrassom (diâmetro biparietal).</div>':"")+
   '<div class="stack" style="margin-top:10px">'+g[4].map(t=>'<div class="sm">• '+esc(t)+'</div>').join("")+'</div>'}
  body='<div class="card grid g2m">'+selF("rpSp","Espécie",Object.keys(GESTS).map(k=>[k,GESTS[k][0]]),R.sp,"S.rep.sp=this.value;saveMod('rep');rerender()")+(R.sp==="dog"?selF("rpRef","Referência",[["cob","Data da cobertura/IA"],["lh","Data do pico de LH"]],R.ref,"S.rep.ref=this.value;saveMod('rep');rerender()"):"")+'<div class="field"><label>Data</label><input class="inp" type="date" value="'+esc(R.dt)+'" onchange="S.rep.dt=this.value;saveMod(\'rep\');rerender()" /></div></div><div class="sm muted">'+esc((GESTS[R.sp]||GESTS.dog)[3])+'</div>'+(out?'<div class="out">'+out+'</div>':'<div class="empty">Informe a data.</div>')}
 if(arg==="p4"){const v=num(R.p4);const z=R.p4!==""?P4.find(x=>v>=x[0]&&v<x[1]):null;
  body='<p class="muted sm" style="margin:0">Momento da cobertura/inseminação na cadela pela progesterona sérica (ng/mL). Valores de conversão variam por método (quimioluminescência × ELISA) — use a tabela do laboratório.</p><div class="card"><div class="field"><label>Progesterona (ng/mL)</label><input class="inp" type="number" step="any" inputmode="decimal" value="'+esc(R.p4)+'" onchange="S.rep.p4=this.value;saveMod(\'rep\');rerender()" /></div></div>'+
  (z?'<div class="out"><div class="lbl">Fase</div><div class="big" style="font-size:20px">'+esc(z[2])+'</div><div class="sm" style="margin-top:6px">'+esc(z[3])+'</div></div>':"")+
  '<div class="card scroll-x"><table class="tbl"><thead><tr><th>P4 (ng/mL)</th><th>Interpretação</th></tr></thead><tbody>'+P4.map(x=>'<tr><td>'+x[0]+(x[1]<999?"–"+x[1]:"+")+'</td><td><b>'+esc(x[2])+'</b><br/><span class="xs">'+esc(x[3])+'</span></td></tr>').join("")+'</tbody></table></div>'+
  '<div class="card"><h3>Outras espécies</h3><p class="sm" style="margin:6px 0 0"><b>Gata:</b> ovulação induzida — 3–4 coberturas/dia por 2–3 dias. <b>Égua:</b> cio de 5–7 dias; ovulação 24–48 h antes do fim do estro (folículo ≥ 35 mm, edema uterino reduzindo); hCG/deslorelina induzem ovulação em ~36–48 h. <b>Vaca:</b> regra AM/PM — cio pela manhã, inseminar à tarde (≈ 12 h após o início); IATF conforme protocolo hormonal.</p></div>'}
 if(arg==="distocia")body='<div class="note bad"><b>Quando intervir no parto (cães e gatos)</b></div><div class="list">'+DIST.map(([a,b])=>'<div class="item"><div class="t">'+esc(a)+'</div><div class="s">'+esc(b)+'</div></div>').join("")+'</div>'+
  '<div class="card"><h3>Conduta médica (somente SEM obstrução)</h3><p class="sm" style="margin:6px 0 0">• Ocitocina em doses BAIXAS: cadela 0,25–4 UI/animal (iniciar com 0,5–2 UI) e gata 0,25–1 UI/animal, IM, a cada 30–60 min, no máximo 2–3 vezes; doses altas causam contrações tetânicas e sofrimento fetal.<br/>• Gluconato de cálcio 10% (0,5–1 mL/5 kg SC diluído, ou IV lento com ECG se hipocalcemia) 15 min antes da ocitocina melhora a força das contrações.<br/>• Glicose se hipoglicemia. Sem resposta após 2 doses → CESARIANA.<br/>• Neonatos: aquecer, aspirar vias aéreas, estimular; Ht/glicose em fracos.</p></div><a class="btn" href="#/bulario/'+((DRUGS.find(d=>/^Ocitocina/.test(d.n))||{}).id||"")+'">Ver monografia da ocitocina</a>';
 return '<div class="stack"><h1>Reprodução</h1>'+tabsBar("repro",[["parto","Data do parto"],["p4","Progesterona / cobertura"],["distocia","Distocia"]],arg)+body+'</div>'+disclaimer()}

/* ---------- 5. Anestesia e cirurgia ---------- */
function vAnes(arg){arg=arg||"asa";const A=DATA.asa||[],J=DATA.jejum||[],C=DATA.check||[],M=DATA.monit||[];let body="";
 if(arg==="asa"){const s=S.asaSel;body='<p class="muted sm" style="margin:0">Classificação do estado físico (ASA). Acrescente “E” para procedimentos de emergência. Mortalidade anestésica aumenta muito a partir de ASA III.</p><div class="list">'+A.map((x,i)=>'<button class="item" style="text-align:left;'+(s===i?"border-color:var(--accent);background:var(--accent-soft)":"")+'" onclick="S.asaSel='+i+';rerender()"><div class="row" style="gap:10px;align-items:flex-start"><b style="font-size:20px;min-width:34px">'+x[0]+'</b><div><div class="t">'+esc(x[1])+'</div><div class="s">'+esc(x[2])+'</div></div></div></button>').join("")+'</div>'+
  (s!=null?'<div class="out"><div class="lbl">Paciente ASA '+A[s][0]+'</div><div class="sm">'+(s<=1?"Risco baixo: exames pré-anestésicos básicos (Ht, PT, ureia/creatinina, glicemia; hemograma e bioquímica completos se > 7 anos).":s===2?"Risco moderado: estabilizar antes (hidratação, eletrólitos, analgesia), hemograma + bioquímica completos, ECG/ecocardiograma se cardiopata, monitoração completa, acesso venoso e fluidoterapia.":"Risco ALTO: estabilização pré-anestésica sempre que possível, protocolo balanceado com fármacos reversíveis e de mínimo efeito cardiovascular (opioide + benzodiazepínico, etomidato/alfaxalona, anestesia locorregional), PA invasiva/Doppler contínua, dois acessos venosos, termo de consentimento com risco elevado.")+'</div><a class="btn sm" style="margin-top:10px" href="#/docs/t-anest" onclick="loadMod(\'dc\',{});S.dc.asa=\''+A[s][0]+'\';saveMod(\'dc\')">Gerar termo de anestesia</a></div>':"")}
 if(arg==="jejum")body='<div class="list">'+J.map(([a,b])=>'<div class="item"><div class="t">'+esc(a)+'</div><div class="s">'+esc(b)+'</div></div>').join("")+'</div><div class="note info">Jejum prolongado aumenta refluxo gastroesofágico, hipoglicemia e hipotermia. Diretrizes AAHA 2020 / WSAVA.</div>';
 if(arg==="check"){const K=S.chk||(S.chk={});let tot=0,ok=0;
  body='<p class="muted sm" style="margin:0">Checklist de cirurgia segura (adaptado da OMS para medicina veterinária). Toque para marcar.</p>'+C.map(([f,items],fi)=>'<div class="card"><h3>'+esc(f)+'</h3><div class="list" style="margin-top:8px">'+items.map((t,i)=>{const k=fi+"_"+i;tot++;if(K[k])ok++;return '<button class="item" style="text-align:left;'+(K[k]?"border-color:var(--ok,#16a34a);background:var(--accent-soft)":"")+'" onclick="S.chk[\''+k+'\']=!S.chk[\''+k+'\'];rerender()"><div class="row" style="gap:10px"><b>'+(K[k]?"☑":"☐")+'</b><span class="sm">'+esc(t)+'</span></div></button>'}).join("")+'</div></div>').join("")+
  '<div class="out"><div class="lbl">Concluído</div><div class="big">'+ok+' / '+tot+'</div>'+(ok===tot?'<div class="note ok" style="margin-top:8px">Checklist completo.</div>':'')+'</div><button class="btn" onclick="S.chk={};rerender()">Zerar checklist</button>'}
 if(arg==="monit")body='<div class="card scroll-x"><table class="tbl"><thead><tr><th>Parâmetro</th><th>Meta trans-anestésica</th></tr></thead><tbody>'+M.map(([a,b])=>'<tr><td>'+esc(a)+'</td><td><b>'+esc(b)+'</b></td></tr>').join("")+'</tbody></table></div>'+
  '<div class="card"><h3>Hipotensão (PAS < 90 / PAM < 60 mmHg)</h3><p class="sm" style="margin:6px 0 0">1) Reduzir o anestésico inalatório (analgesia adequada permite menor CAM). 2) Bolus de cristaloide 3–10 mL/kg em 15 min (ou coloide 2–5 mL/kg). 3) Bradicardia associada: atropina 0,02–0,04 mg/kg ou glicopirrolato 0,005–0,01 mg/kg IV. 4) Persistente: dopamina 5–10 mcg/kg/min, dobutamina 2–10 mcg/kg/min, efedrina 0,03–0,1 mg/kg IV ou noradrenalina 0,05–0,5 mcg/kg/min.</p></div>'+
  '<div class="card"><h3>Hipotermia, hipercapnia, apneia</h3><p class="sm" style="margin:6px 0 0">• Aquecimento ativo desde a MPA (ar forçado, colchão térmico, fluidos aquecidos).<br/>• EtCO₂ > 50 mmHg: ventilação assistida/controlada (VC 10–15 mL/kg, FR 8–12).<br/>• SpO₂ < 95%: checar posição da sonda, desconexão, oxigênio, ventilação.</p></div><a class="btn" href="#/calc/cri">Infusões contínuas (CRI)</a>';
 return '<div class="stack"><h1>Anestesia & cirurgia</h1>'+tabsBar("anestesia",[["asa","ASA"],["jejum","Jejum"],["check","Checklist"],["monit","Monitoração"]],arg)+body+'</div>'+disclaimer()}

/* ---------- 6. Emergência e triagem ---------- */
const CRASH=[["C","Cardiovascular","FC, pulso (qualidade, déficit), mucosas, TPC, extremidades frias, PA. Choque: taquicardia (cães) ou BRADICARDIA + hipotermia (gatos), mucosas pálidas, TPC > 2 s."],["R","Respiratório","FR, padrão (obstrutivo inspiratório × restritivo expiratório), sons pulmonares, cianose. Oxigênio ANTES de manipular; TFAST."],["A","Abdome","Distensão, dor, ferimentos, fluido livre (AFAST), DVG (abdome timpânico em raça grande)."],["S","Coluna (spine)","Dor, déficits, Schiff-Sherrington, imobilizar em prancha se trauma."],["H","Cabeça (head)","Consciência, pupilas, reflexos, TCE (escala de coma), epistaxe, olhos."],["P","Pelve","Fraturas, períneo, reto, uretra."],["L","Membros (limbs)","Fraturas, luxações, ferimentos; imobilizar."],["A","Artérias","Pulsos periféricos, hemorragias — compressão direta."],["N","Nervos","Exame neurológico periférico, reflexos."]];
function vEmerg(arg){arg=arg||"triagem";let body="";
 if(arg==="triagem")body='<div class="note bad"><b>Prioridade imediata</b> (ABC): obstrução de via aérea, apneia, cianose, parada (RCP), hemorragia ativa, convulsão em curso, choque, DVG, obstrução uretral, trauma grave, intoxicação aguda.</div><div class="card"><h3>A CRASH PLAN — exame do politraumatizado</h3><div class="list" style="margin-top:8px">'+CRASH.map(([l,n,t])=>'<div class="item"><div class="row" style="gap:10px;align-items:flex-start"><b style="font-size:20px;min-width:22px">'+l+'</b><div><div class="t">'+n+'</div><div class="s">'+esc(t)+'</div></div></div></div>').join("")+'</div></div>'+
  '<div class="card"><h3>Base mínima de emergência</h3><p class="sm" style="margin:6px 0 0">Ht/PT, glicemia, lactato, eletrólitos (Na, K, Cl, Ca ionizado), ureia/creatinina, gasometria, densidade urinária, esfregaço sanguíneo, PA, ECG, SpO₂, AFAST/TFAST.</p></div><div class="actions"><a class="btn" href="#/calc/rcp">RCP & doses</a><a class="btn" href="#/escalas/coma">Escala de coma</a><a class="btn" href="#/lab/gaso">Gasometria</a></div>';
 if(arg==="choque"){const E=loadMod("sh",{sp:"dog",fc:"",pas:""});const fc=num(E.fc),pas=num(E.pas);let out="";
  if(fc&&pas){const si=fc/pas;out='<div class="lbl">Índice de choque (FC / PAS)</div><div class="big">'+fmt(si,2)+'</div><div class="note '+(si>=1?"bad":si>=0.9?"warn":"ok")+'" style="margin-top:8px">'+(si>=1?"≥ 1,0: compatível com CHOQUE/hipovolemia — reposição volêmica (bolus de cristaloide 10–20 mL/kg em cães em 15 min, reavaliar), controlar hemorragias, lactato seriado.":si>=0.9?"0,9–1,0: limítrofe — reavaliar perfusão e lactato.":"< 0,9: improvável choque hipovolêmico grave (cães).")+(E.sp==="cat"?" GATOS: o índice é pouco validado — gatos em choque costumam estar BRADICÁRDICOS e hipotérmicos (tríade); bolus menores (5–10 mL/kg) e aquecer.":"")+'</div>'}
  body='<p class="muted sm" style="margin:0">Índice de choque em cães: referência ~0,9 (Porter et al., 2013); valores ≥ 1 sugerem choque.</p><div class="card grid g2m">'+selF("shSp","Espécie",[["dog","Cão"],["cat","Gato"]],E.sp,"S.sh.sp=this.value;saveMod('sh');rerender()")+'<div class="field"><label>FC (bpm)</label><input class="inp" type="number" value="'+esc(E.fc)+'" onchange="S.sh.fc=this.value;saveMod(\'sh\');rerender()" /></div><div class="field"><label>PAS (mmHg)</label><input class="inp" type="number" value="'+esc(E.pas)+'" onchange="S.sh.pas=this.value;saveMod(\'sh\');rerender()" /></div></div>'+(out?'<div class="out">'+out+'</div>':"")+
  '<div class="card scroll-x"><h3>Tipos de choque</h3><table class="tbl" style="margin-top:8px"><tbody><tr><td><b>Hipovolêmico</b></td><td>Hemorragia, desidratação grave → cristaloides, hemoderivados.</td></tr><tr><td><b>Distributivo</b></td><td>Sepse, anafilaxia → fluidos + vasopressor (noradrenalina); anafilaxia: ADRENALINA 0,01 mg/kg IM/IV.</td></tr><tr><td><b>Cardiogênico</b></td><td>ICC, arritmias → NÃO dar bolus de fluido; oxigênio, furosemida, pimobendan/dobutamina.</td></tr><tr><td><b>Obstrutivo</b></td><td>DVG, tamponamento cardíaco, pneumotórax hipertensivo → descompressão (trocarização, pericardiocentese, toracocentese).</td></tr></tbody></table></div>'}
 if(arg==="fast")body='<div class="card"><h3>AFAST — 4 janelas abdominais</h3><p class="sm" style="margin:6px 0 0">1) Diafragmático-hepática (DH) · 2) Esplenorrenal (SR) · 3) Cistocólica (CC) · 4) Hepatorrenal (HR). Decúbito lateral direito ou esternal.</p><table class="tbl" style="margin-top:8px"><thead><tr><th>Escore de fluido abdominal (AFS)</th><th>Significado</th></tr></thead><tbody><tr><td>0</td><td>Sem fluido livre.</td></tr><tr><td>1–2</td><td>Hemorragia pequena — geralmente tratamento conservador; repetir em 4 h.</td></tr><tr><td>3–4</td><td>Hemorragia significativa — anemia provável, considerar transfusão e laparotomia se instabilidade persistente.</td></tr></tbody></table><p class="xs muted" style="margin-top:6px">Fluido livre: abdominocentese guiada — comparar Ht do líquido × sangue (hemoabdome), creatinina/K do líquido × soro (uroabdome: relação > 2:1 creatinina / > 1,4:1 K), lactato/glicose (peritonite séptica: glicose do líquido 20 mg/dL menor que sangue), bilirrubina (biliar).</p></div>'+
  '<div class="card"><h3>TFAST / Vet BLUE — tórax</h3><p class="sm" style="margin:6px 0 0">• <b>Pneumotórax:</b> ausência do sinal de deslizamento pleural (“glide sign”) e de linhas B; “ponto pulmonar” confirma. Toracocentese diagnóstica-terapêutica.<br/>• <b>Efusão pleural/pericárdica:</b> anecoica entre pulmão e parede / ao redor do coração; tamponamento: colapso de átrio direito → pericardiocentese.<br/>• <b>Linhas B (“rockets”):</b> > 3 por janela = síndrome alvéolo-intersticial (edema cardiogênico, pneumonia, contusão).<br/>• Átrio esquerdo:aorta > 1,5 (vista transversal) sugere ICC esquerda.</p></div>';
 if(arg==="transf")body='<div class="card"><h3>Cães — sistema DEA</h3><p class="sm" style="margin:6px 0 0">• Não possuem aloanticorpos naturais clinicamente relevantes: a PRIMEIRA transfusão raramente causa reação aguda grave, mas TIPAR para DEA 1 (doador ideal DEA 1-negativo) é recomendado.<br/>• Após uma transfusão, o receptor pode formar anticorpos em 4–14 dias → PROVA CRUZADA obrigatória em transfusões subsequentes (> 4 dias da primeira).<br/>• Cadelas que já pariram: fazer prova cruzada.</p></div>'+
  '<div class="card"><h3>Gatos — sistema AB (TIPAGEM SEMPRE)</h3><p class="sm" style="margin:6px 0 0">• Possuem aloanticorpos NATURAIS: gato tipo B tem anti-A forte → transfusão de sangue A em gato B = reação hemolítica fatal com poucos mL.<br/>• NÃO existe doador universal. Tipar receptor e doador SEMPRE e fazer prova cruzada (maior e menor), inclusive na primeira transfusão.<br/>• Antígeno Mik: pode haver incompatibilidade mesmo com tipo compatível — prova cruzada.<br/>• Raças com maior frequência de tipo B: British Shorthair, Devon Rex, Cornish Rex, Ragdoll; isoeritrólise neonatal em filhotes A de mãe B.</p></div>'+
  '<div class="card"><h3>Prova cruzada (técnica em tubo — resumo)</h3><p class="sm" style="margin:6px 0 0">Maior: hemácias do DOADOR lavadas (suspensão 3–5%) + plasma do RECEPTOR. Menor: hemácias do receptor + plasma do doador. Controle: hemácias + plasma do mesmo animal. Incubar 15–30 min, centrifugar e avaliar aglutinação/hemólise macro e microscopicamente. Qualquer aglutinação verdadeira = incompatível.</p></div>'+
  '<div class="card"><h3>Durante a transfusão</h3><p class="sm" style="margin:6px 0 0">Filtro de 170–260 µm. Velocidade 0,25–1 mL/kg/h nos primeiros 15–30 min (observar), depois completar em até 4 h. Monitorar T, FC, FR, PA a cada 15–30 min. Reações: febre, urticária, vômito, hemólise (hemoglobinúria), dispneia (TACO/TRALI) → INTERROMPER, avaliar e tratar.</p></div><a class="btn" href="#/calc/transf">Calcular volume a transfundir</a>';
 return '<div class="stack"><h1>Emergência & triagem</h1>'+tabsBar("emergencia",[["triagem","Triagem"],["choque","Índice de choque"],["fast","AFAST/TFAST"],["transf","Transfusão"]],arg)+body+'</div>'+disclaimer()}

/* ---------- 7. Produção animal ---------- */
const ECC5=[[1,"Muito magra","Costelas, processos espinhosos e transversos, tuberosidades ilíaca e isquiática muito visíveis; sem gordura; atrofia muscular."],[2,"Magra","Costelas individualmente visíveis; processos espinhosos proeminentes; pouca cobertura sobre a garupa."],[3,"Moderada (ideal)","Costelas pouco visíveis; cobertura moderada sobre o lombo e a garupa; inserção da cauda sem depressão profunda."],[4,"Gorda","Costelas não visíveis; acúmulo de gordura na inserção da cauda e na garupa; lombo arredondado."],[5,"Obesa","Estrutura óssea não palpável; depósitos evidentes de gordura na cauda, peito e flanco; mobilidade reduzida."]];
function vProd(arg){arg=arg||"lote";let body="";
 if(arg==="lote"){const L=loadMod("lote",{sp:"cattle",drug:"",n:"",w:"",dose:"",fr:""});const sps=[["cattle","Bovino"],["sr","Ovino/caprino"],["pig","Suíno"],["horse","Equino"]];
  const list=DRUGS.filter(d=>d.d[L.sp]&&d.d[L.sp][0]!=null).sort((a,b)=>a.n.localeCompare(b.n));const d=list.find(x=>x.id===L.drug)||list[0];
  let out="";if(d){const e=d.d[L.sp];const dose=L.dose!==""?num(L.dose):(e[5]!=null?e[5]:e[0]);const n=num(L.n),w=num(L.w),c=d.conc||0;
   if(n&&w){const mgA=dose*w,mlA=c?mgA/c:null,tot=mlA!=null?mlA*n:null;const fr=num(L.fr);
    out='<div class="res-grid"><div class="res"><b>'+fmt(mgA)+' mg</b><span>por animal ('+fmt(dose)+' mg/kg × '+fmt(w)+' kg)</span></div>'+(mlA!=null?'<div class="res"><b>'+fmt(mlA)+' mL</b><span>por animal ('+fmt(c)+' mg/mL)</span></div><div class="res"><b>'+fmt(tot)+' mL</b><span>total para '+n+' animais</span></div>'+(fr?'<div class="res"><b>'+Math.ceil(tot*1.1/fr)+'</b><span>frasco(s) de '+fr+' mL (com 10% de perda)</span></div>':""):'<div class="res"><b>'+fmt(mgA*n/1000,2)+' g</b><span>total do princípio ativo</span></div>')+'</div>'+
    '<div class="sm" style="margin-top:8px">Via: '+esc(e[2]||"")+' · '+esc(e[3]||"")+(e[4]?" · "+esc(e[4]):"")+'</div>'+(dose<e[0]||dose>e[1]?'<div class="note bad" style="margin-top:8px">Dose fora da faixa de referência ('+e[0]+'–'+e[1]+' mg/kg).</div>':"")+
    '<div class="note warn" style="margin-top:8px"><b>Carência:</b> '+esc(d.wd||"Respeite o período de carência do produto registrado no MAPA (carne, leite, ovos).")+'</div>'+((d.x||{})[L.sp]?'<div class="note bad" style="margin-top:8px"><b>Atenção:</b> '+esc(d.x[L.sp])+'</div>':"")+
    '<div class="sm muted" style="margin-top:8px">Pese ou estime o peso por fita; em lotes heterogêneos, separe por faixas de peso (subdosagem favorece resistência). Volume IM máximo por ponto: bovinos ~10–15 mL, ovinos/caprinos/suínos ~5 mL.</div>'}}
  const ins=(k,l)=>'<div class="field"><label>'+l+'</label><input class="inp" type="number" step="any" inputmode="decimal" value="'+esc(L[k])+'" onchange="S.lote.'+k+'=this.value;saveMod(\'lote\');rerender()" /></div>';
  body='<p class="muted sm" style="margin:0">Dose para o lote inteiro (vermifugação, antimicrobianos, vacinas por peso).</p><div class="card grid g2m">'+selF("ltSp","Espécie",sps,L.sp,"S.lote.sp=this.value;S.lote.drug='';S.lote.dose='';saveMod('lote');rerender()")+selF("ltD","Fármaco",list.map(x=>[x.id,x.n]),d?d.id:"","S.lote.drug=this.value;S.lote.dose='';saveMod('lote');rerender()")+ins("n","Nº de animais")+ins("w","Peso médio (kg)")+ins("dose","Dose (mg/kg) — vazio = usual"+(d?" ("+d.d[L.sp][0]+"–"+d.d[L.sp][1]+")":""))+ins("fr","Volume do frasco (mL) — opcional")+'</div>'+(out?'<div class="out">'+out+'</div>':'<div class="empty">Informe o número de animais e o peso médio.</div>')}
 if(arg==="ecc"){const e=S.ecc5;body='<p class="muted sm" style="margin:0">Escore de condição corporal de bovinos (escala 1–5; aceitas frações de 0,25/0,5).</p><div class="list">'+ECC5.map(([n,t,dsc])=>'<button class="item" style="text-align:left;'+(e===n?"border-color:var(--accent);background:var(--accent-soft)":"")+'" onclick="S.ecc5='+n+';rerender()"><div class="row" style="gap:10px;align-items:flex-start"><b style="font-size:20px;min-width:22px">'+n+'</b><div><div class="t">'+t+'</div><div class="s">'+esc(dsc)+'</div></div></div></button>').join("")+'</div>'+
  '<div class="card scroll-x"><h3>Metas</h3><table class="tbl" style="margin-top:8px"><tbody><tr><td>Vaca leiteira — secagem/parto</td><td><b>3,0–3,5</b> (evitar > 3,75: cetose, lipidose, deslocamento de abomaso)</td></tr><tr><td>Vaca leiteira — pico de lactação</td><td>Perda máxima de 0,5–1 ponto; ≥ 2,5</td></tr><tr><td>Vaca de corte — parto e estação de monta</td><td><b>≥ 3,0</b> (abaixo disso, anestro pós-parto prolongado)</td></tr><tr><td>Novilhas na 1ª inseminação</td><td>3,0–3,25 e ~60–65% do peso adulto</td></tr></tbody></table></div>'+(e?'<div class="out"><div class="sm">'+(e<=2?"Abaixo do ideal: revisar oferta de energia/proteína, parasitismo, doenças crônicas (tristeza parasitária, verminose); impacto direto na reprodução.":e>=4?"Acima do ideal: risco de distocia, cetose, lipidose hepática e doenças metabólicas no periparto — ajustar dieta de pré-parto.":"Condição adequada para a maioria das fases.")+'</div></div>':"")}
 if(arg==="carencia"){const C=loadMod("car",{dt:"",carne:"",leite:""});const d=parseDate(C.dt);const ins=(k,l,t)=>'<div class="field"><label>'+l+'</label><input class="inp" type="'+(t||"number")+'" value="'+esc(C[k])+'" onchange="S.car.'+k+'=this.value;saveMod(\'car\');rerender()" /></div>';
  let out="";if(d){const hoje=new Date();const L=[];if(C.carne!=="")L.push(["Abate liberado a partir de",addDays(d,num(C.carne)+1)]);if(C.leite!=="")L.push(["Leite liberado a partir de",addDays(d,Math.ceil(num(C.leite)/ (C.lu==="h"?24:1))+1)]);
   out=L.map(([t,x])=>{const ok=x<=hoje;return '<div class="note '+(ok?"ok":"bad")+'"><b>'+t+': '+dBR(x)+'</b> — '+(ok?"LIBERADO.":"BLOQUEADO (faltam "+Math.ceil((x-hoje)/864e5)+" dia(s)).")+'</div>'}).join("")}
  body='<p class="muted sm" style="margin:0">Informe a data da ÚLTIMA aplicação e os períodos de carência da BULA do produto registrado (eles variam entre marcas, vias e espécies).</p><div class="card grid g2m">'+ins("dt","Data da última aplicação","date")+ins("carne","Carência carne (dias)")+ins("leite","Carência leite")+selF("carLu","Unidade da carência do leite",[["d","dias"],["h","horas"]],C.lu||"d","S.car.lu=this.value;saveMod('car');rerender()")+'</div>'+(out?'<div class="stack">'+out+'</div>':"")+
  '<div class="note warn">Uso extrabula em animais de produção: o MV assume a responsabilidade e deve adotar carência ampliada (referência internacional: no mínimo 28 dias carne e 7 dias leite quando não há dado). Fármacos PROIBIDOS em animais de produção no Brasil incluem cloranfenicol, nitrofuranos, nitroimidazóis (metronidazol), anabolizantes e outros — confira as normas do MAPA.</div>'}
 return '<div class="stack"><h1>Produção animal</h1>'+tabsBar("producao",[["lote","Dose para o lote"],["ecc","Condição corporal (1–5)"],["carencia","Carência"]],arg)+body+'</div>'+disclaimer()}

/* ---------- 8. Quiz / trilhas de estudo ---------- */
function shuf(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function pick(a){return a[Math.floor(Math.random()*a.length)]}
function qOpts(right,pool){const o=[right];for(const x of shuf(pool)){if(o.length>=4)break;if(x&&!o.includes(x))o.push(x)}return o.length>=2?shuf(o):null}
const QUIZ_T={
 farm:["Farmacologia (classe)",()=>{const cn=x=>CLS[x.c]&&CLS[x.c].n;const d=pick(DRUGS.filter(cn));const o=qOpts(cn(d),DRUGS.map(cn));return o&&{q:"A qual classe pertence "+d.n+"?",o,a:cn(d),ex:d.m||""}}],
 ctl:["Controlados (Portaria 344/98)",()=>{const L={A1:"Lista A1 — Notificação A (amarela)",B1:"Lista B1 — Notificação B (azul)",C1:"Lista C1 — Receita de Controle Especial (2 vias)",C5:"Lista C5 — anabolizantes",ATB:"Antimicrobiano — receita em 2 vias com retenção",CANN:"Cannabis — receita especial"};const ds=DRUGS.filter(x=>L[x.ctl]);const d=pick(ds);return {q:"Que tipo de receita exige "+d.n+"?",o:shuf([L[d.ctl]].concat(shuf(Object.values(L).filter(x=>x!==L[d.ctl])).slice(0,3))),a:L[d.ctl],ex:""}}],
 tox:["Toxicologia (antídotos)",()=>{const ts=TOX.filter(t=>t.ant&&!/^não há/i.test(t.ant));const t=pick(ts);const o=qOpts(t.ant,ts.map(x=>x.ant));return o&&{q:"Qual o antídoto/tratamento específico para intoxicação por "+t.n+"?",o,a:t.ant,ex:t.tx||""}}],
 inter:["Interações",()=>{const r=pick(INTER);const A=(IG[r.a]||[r.a])[0],B=(IG[r.b]||[r.b]).find(n=>n!==A)||r.b;return {q:"Qual a gravidade da interação entre "+A+" e "+B+"?",o:["Grave","Moderada","Leve"],a:r.sev,ex:r.eff+" — "+r.mech}}],
 derm:["Dermatologia",()=>{const ds=(DATA.derm||[]).filter(x=>x.cli);const d=pick(ds);return {q:"Quadro: “"+d.cli.slice(0,220)+(d.cli.length>220?"…":"")+"” — qual a dermatopatia mais provável?",o:qOpts(d.n,ds.map(x=>x.n)),a:d.n,ex:d.ex||""}}],
 lab:["Laboratório",()=>{const x=pick(LABREF.filter(y=>y[6].length>3));const sp=pick(["dog","cat"]);const r=sp==="cat"?x[4]:x[3];const o=qOpts(r.join("–"),LABREF.filter(y=>y[2]===x[2]&&y!==x).map(y=>(sp==="cat"?y[4]:y[3]).join("–")).concat([[r[0]*1.5,r[1]*1.5].map(v=>+v.toFixed(2)).join("–"),[+(r[0]*0.6).toFixed(2),+(r[1]*0.7).toFixed(2)].join("–")]));return o&&{q:"Faixa de referência usual de "+x[1]+(x[2]?" ("+x[2]+")":"")+" em "+(sp==="cat"?"GATOS":"CÃES")+":",o,a:r.join("–"),ex:"Aumento: "+x[6]}}],
 repro:["Reprodução",()=>{const k=pick(Object.keys(GESTS));const g=GESTS[k];const o=qOpts(String(g[1]),Object.values(GESTS).map(x=>String(x[1])));return o&&{q:"Duração média da gestação — "+g[0]+" (dias):",o,a:String(g[1]),ex:g[3]}}],
 casos:["Casos clínicos",()=>{const c=pick(CASES.filter(x=>x.spec));const o=qOpts(c.spec,CASES.map(x=>x.spec));return o&&{q:"Caso: “"+c.title+"” — a qual especialidade pertence?",o,a:c.spec,ex:(c.pts||[])[0]||""}}]
};
function newQuiz(t){const g=QUIZ_T[t]||QUIZ_T.farm;const Q=[];let tries=0;while(Q.length<10&&tries++<200){const q=g[1]();if(q&&q.o&&q.o.includes(q.a)&&!Q.some(z=>z.q===q.q))Q.push(q)}S.qz={t,Q,i:0,ok:0,ans:null}}
function vQuiz(arg){const H=store.get("quiz",{});
 if(!arg||!QUIZ_T[arg]){S.qz=null;return '<div class="stack"><h1>Quiz & trilhas de estudo</h1><p class="muted sm" style="margin:0">Perguntas geradas a partir do banco de dados do app (10 por rodada). Seu melhor resultado fica salvo neste aparelho.</p><div class="list">'+Object.entries(QUIZ_T).map(([k,[n]])=>'<a class="item" href="#/quiz/'+k+'"><div class="row between"><div class="t">'+n+'</div><span class="xs muted">'+(H[k]?"melhor: "+H[k].best+"/10 · "+H[k].n+" rodada(s)":"novo")+'</span></div></a>').join("")+'</div></div>'}
 if(!S.qz||S.qz.t!==arg)newQuiz(arg);const Z=S.qz,nome=QUIZ_T[arg][0];
 if(Z.i>=Z.Q.length){const h=H[arg]||{best:0,n:0};h.n++;if(Z.ok>h.best)h.best=Z.ok;if(!Z.saved){H[arg]=h;store.set("quiz",H);Z.saved=1}
  return '<div class="stack"><h1>'+esc(nome)+'</h1><div class="out"><div class="lbl">Resultado</div><div class="big">'+Z.ok+' / '+Z.Q.length+'</div><div class="sm">'+(Z.ok>=9?"Excelente!":Z.ok>=7?"Muito bom.":Z.ok>=5?"Bom — revise os erros.":"Vale revisar o conteúdo deste tema.")+' Melhor: '+h.best+'/10.</div></div><div class="actions"><button class="btn pri" onclick="newQuiz(\''+arg+'\');rerender()">Nova rodada</button><a class="btn" href="#/quiz">Outros temas</a></div></div>'}
 const q=Z.Q[Z.i];return '<div class="stack"><div class="row between"><h1 style="margin:0">'+esc(nome)+'</h1><span class="tag">'+(Z.i+1)+'/'+Z.Q.length+' · '+Z.ok+' ✓</span></div><div class="card"><p style="margin:0;font-weight:700">'+esc(q.q)+'</p><div class="list" style="margin-top:12px">'+q.o.map((o,j)=>{let st="";if(Z.ans!=null){if(o===q.a)st="border-color:#16a34a;background:rgba(22,163,74,.12)";else if(j===Z.ans)st="border-color:#dc2626;background:rgba(220,38,38,.12)"}return '<button class="item" style="text-align:left;'+st+'" '+(Z.ans!=null?"disabled":"")+' onclick="qAns('+j+')"><span class="sm">'+esc(o)+'</span></button>'}).join("")+'</div>'+
 (Z.ans!=null?'<div class="note '+(q.o[Z.ans]===q.a?"ok":"bad")+'" style="margin-top:12px"><b>'+(q.o[Z.ans]===q.a?"Correto!":"Resposta: "+esc(q.a))+'</b>'+(q.ex?'<br/><span class="sm">'+esc(String(q.ex).slice(0,400))+'</span>':"")+'</div><button class="btn pri block" style="margin-top:10px" onclick="S.qz.i++;S.qz.ans=null;rerender()">'+(Z.i+1<Z.Q.length?"Próxima":"Ver resultado")+'</button>':"")+'</div><a class="btn sm ghost" href="#/quiz">Sair</a></div>'}
function qAns(j){const Z=S.qz;if(Z.ans!=null)return;Z.ans=j;if(Z.Q[Z.i].o[j]===Z.Q[Z.i].a)Z.ok++;rerender()}

/* ---------- 9. Atualização de conteúdo sem novo APK ---------- */
const DATA_URL="https://leolimauk.github.io/Leo-Lima-vet/data.json";
function checkDataUpdate(manual){if(!navigator.onLine){if(manual)toast("Sem conexão");return}
 fetch(DATA_URL+"?t="+Date.now(),{cache:"no-store"}).then(r=>r.ok?r.json():null).then(j=>{if(!j||!j.v||!j.drugs){if(manual)toast("Não foi possível verificar");return}
  if(j.v>(DATA.v||0)){try{localStorage.setItem("lmv_data",JSON.stringify(j));store.set("dataNew",1)}catch(e){if(manual)toast("Sem espaço para salvar");return}
   toast("Conteúdo atualizado — reabra o app para aplicar");if(manual)setTimeout(()=>location.reload(),900)}else if(manual)toast("Conteúdo já está na versão mais recente")}).catch(()=>{if(manual)toast("Não foi possível verificar")})}
function dataVer(){return DATA.v?new Date(DATA.v).toLocaleString("pt-BR"):"—"}
setTimeout(()=>checkDataUpdate(false),4000);
